"use strict";(self.webpackChunkibm_gantt_chart_docs=self.webpackChunkibm_gantt_chart_docs||[]).push([[583],{"./src/docs/introduction.stories.js"(__unused_webpack_module,__webpack_exports__,__webpack_require__){__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{Concepts:()=>Concepts,GettingStarted:()=>GettingStarted,Overview:()=>Overview,__namedExportsOrder:()=>__namedExportsOrder,default:()=>introduction_stories});var marked_esm=__webpack_require__("../../node_modules/marked/lib/marked.esm.js");__webpack_require__("./src/docs/github-markdown.css");const renderMarkdown=md=>`<div class="markdown-body" style="margin: 1rem;">${marked_esm.xI.parse(md)}</div>`,introduction_stories={title:"Guides/Introduction",parameters:{storySource:{source:"import { marked } from 'marked';\n\nimport gettingStarted from '../../../ibm-gantt-chart/README.md';\nimport concepts from './concepts.md';\nimport overview from './overview.md';\n\nimport './github-markdown.css';\n\nconst renderMarkdown = (md) => `<div class=\"markdown-body\" style=\"margin: 1rem;\">${marked.parse(md)}</div>`;\n\nexport default {\n  title: 'Guides/Introduction',\n  parameters: { options: { showPanel: false } },\n};\n\nexport const GettingStarted = {\n  render: () => renderMarkdown(gettingStarted),\n};\n\nexport const Overview = {\n  render: () => renderMarkdown(overview),\n};\n\nexport const Concepts = {\n  render: () => renderMarkdown(concepts),\n};\n",locationsMap:{"getting-started":{startLoc:{col:30,line:16},endLoc:{col:1,line:18},startBody:{col:30,line:16},endBody:{col:1,line:18}},overview:{startLoc:{col:24,line:20},endLoc:{col:1,line:22},startBody:{col:24,line:20},endBody:{col:1,line:22}},concepts:{startLoc:{col:24,line:24},endLoc:{col:1,line:26},startBody:{col:24,line:24},endBody:{col:1,line:26}}}},options:{showPanel:!1}}},GettingStarted={render:()=>renderMarkdown("# ibm-gantt-chart\r\n\r\n## Usage\r\n\r\nHere is a simple example to illustrate how to include the Gantt into a web page.<br/>\r\n\r\n```html\r\n<html>\r\n  <head>\r\n    <title>Simple Gantt</title>\r\n    <link href=\"[...]/ibm-gantt-chart.css\" rel=\"stylesheet\" />\r\n    <script src=\"[...]/ibm-gantt-chart.js\"><\/script>\r\n\r\n    \x3c!--  Page styles  --\x3e\r\n    <style>\r\n      html {\r\n        height: 100%;\r\n      }\r\n      body {\r\n        height: 100%;\r\n        margin: 0;\r\n        padding: 0;\r\n      }\r\n      #gantt {\r\n        height: 100%;\r\n      }\r\n    </style>\r\n  </head>\r\n  <body>\r\n    <div id=\"gantt\"></div>\r\n\r\n    <script>\r\n      var data = [\r\n        {\r\n          id: 'NURSES+Anne',\r\n          name: 'Anne',\r\n          activities: [\r\n            {\r\n              id: 'SHIFTS+Emergency+Monday+2+8',\r\n              name: 'Emergency',\r\n              start: 1474880400000,\r\n              end: 1474902000000,\r\n            },\r\n          ],\r\n        },\r\n        {\r\n          id: 'NURSES+Bethanie',\r\n          name: 'Bethanie',\r\n          activities: [],\r\n        },\r\n        {\r\n          id: 'NURSES+Betsy',\r\n          name: 'Betsy',\r\n          activities: [\r\n            {\r\n              id: 'SHIFTS+Emergency+Wednesday+12+18',\r\n              name: 'Emergency',\r\n              start: 1475089200000,\r\n              end: 1475110800000,\r\n            },\r\n            {\r\n              id: 'SHIFTS+Emergency+Saturday+12+20',\r\n              name: 'Emergency',\r\n              start: 1475348400000,\r\n              end: 1475377200000,\r\n            },\r\n            {\r\n              id: 'SHIFTS+Consultation+Friday+8+12',\r\n              name: 'Consultation',\r\n              start: 1475247600000,\r\n              end: 1475262000000,\r\n            },\r\n          ],\r\n        },\r\n        {\r\n          id: 'NURSES+Cathy',\r\n          name: 'Cathy',\r\n          activities: [\r\n            {\r\n              id: 'SHIFTS+Emergency+Sunday+20+2',\r\n              name: 'Emergency',\r\n              start: 1475463600000,\r\n              end: 1475485200000,\r\n            },\r\n            {\r\n              id: 'SHIFTS+Emergency+Saturday+12+20',\r\n              name: 'Emergency',\r\n              start: 1475348400000,\r\n              end: 1475377200000,\r\n            },\r\n            {\r\n              id: 'SHIFTS+Emergency+Monday+18+2',\r\n              name: 'Emergency',\r\n              start: 1474938000000,\r\n              end: 1474966800000,\r\n            },\r\n          ],\r\n        },\r\n        {\r\n          id: 'NURSES+Cindy',\r\n          name: 'Cindy',\r\n          activities: [\r\n            {\r\n              id: 'SHIFTS+Emergency+Saturday+20+2',\r\n              name: 'Emergency',\r\n              start: 1475377200000,\r\n              end: 1475398800000,\r\n            },\r\n            {\r\n              id: 'SHIFTS+Consultation+Friday+8+12',\r\n              name: 'Consultation',\r\n              start: 1475247600000,\r\n              end: 1475262000000,\r\n            },\r\n            {\r\n              id: 'SHIFTS+Consultation+Tuesday+8+12',\r\n              name: 'Consultation',\r\n              start: 1474988400000,\r\n              end: 1475002800000,\r\n            },\r\n          ],\r\n        },\r\n      ];\r\n      var config = {\r\n        data: {\r\n          // Configures how to fetch resources for the Gantt\r\n          resources: {\r\n            data: data, // resources are provided in an array. Instead, we could configure a request to the server.\r\n            // Activities of the resources are provided along with the 'activities' property of resource objects.\r\n            // Alternatively, they could be listed from the 'data.activities' configuration.\r\n            activities: 'activities',\r\n            name: 'name', // The name of the resource is provided with the name property of the resource object.\r\n            id: 'id', // The id of the resource is provided with the id property of the resource object.\r\n          },\r\n          // Configures how to fetch activities for the Gantt\r\n          // As activities are provided along with the resources, this section only describes how to create\r\n          // activity Gantt properties from the activity model objects.\r\n          activities: {\r\n            start: 'start', // The start of the activity is provided with the start property of the model object\r\n            end: 'end', // The end of the activity is provided with the end property of the model object\r\n            name: 'name', // The name of the activity is provided with the name property of the model object\r\n          },\r\n        },\r\n        // Configure a toolbar associated with the Gantt\r\n        toolbar: [\r\n          'title',\r\n          'search',\r\n          'separator',\r\n          {\r\n            type: 'button',\r\n            text: 'Refresh',\r\n            fontIcon: 'fa fa-refresh fa-lg',\r\n            onclick: function(ctx) {\r\n              ctx.gantt.draw();\r\n            },\r\n          },\r\n          'fitToContent',\r\n          'zoomIn',\r\n          'zoomOut',\r\n        ],\r\n        title: 'Simple Gantt', // Title for the Gantt to be displayed in the toolbar\r\n      };\r\n      new Gantt('gantt' /* the id of the DOM element to contain the Gantt chart */, config);\r\n    <\/script>\r\n  </body>\r\n</html>\r\n```\r\n\r\nIncluding this Gantt chart into a Web page consists on:\r\n\r\n- Including the Gantt library bundle files, one Javascript and one CSS file.\r\n- Create DOM element that will contain the Gantt chart. This is done here with the declaration:\r\n  ```\r\n  <div id=\"gantt\"></div>\r\n  ```\r\n- Create a Javascript object to configure the Gantt.\r\n- Instantiate the Gantt chart object with this configuration object and the id of the DOM element to contain the Gantt chart.\r\n  As explained below, the Gantt library is packaged for several frameworks (jQuery, React or as a pure Javascript component).\r\n  Use the one that fits the need of your page.\r\n  For this example, the Vanilla Javascript component is used.\r\n\r\n## Data\r\n\r\nIn the first example, data is provided to the Gantt as an array of resources created on the client side to get a self contained example.\r\nThe Gantt can also be configured to fetch data from a server and map this data into a Gantt model.\r\nThe example [Activity chart](/examples/activity_chart/index.html) shows how customizable the process of fetching user data and mapping it to a Gantt model can be.\r\n\r\n## Formatting, filtering and other features\r\n\r\nThe Gantt library is rich of features for formatting and navigating into user data.\r\nThe [Gantt examples](/examples) illustrate how to configure and use these features.\r\n\r\n## Gantt packages\r\n\r\nThe simple Gantt chart example uses the Gantt chart as a Vanilla Javascript component.\r\nThe Gantt library also distributes the Gantt as a React component and a jQuery component.\r\nFor those packages, the configuration of the Gantt is done using the same configuration object.\r\nOnly the bundle files to include and the how the Gantt object is constructed differ.\r\n\r\n1. The Gantt as a React component\r\n\r\n   ```js\r\n   import React from 'react';\r\n   import ReactDOM from 'react-dom';\r\n   import GanttChart from 'ibm-gantt-chart-react';\r\n\r\n   import 'ibm-gantt-chart/dist/ibm-gantt-chart.css';\r\n\r\n   const config = { ... }; // Same format as in the simple Gantt example.\r\n\r\n   ReactDOM.render(<GanttChart config={config} />, document.getElementById('gantt'));\r\n   ```\r\n\r\n2) The Gantt as a jQuery component\r\n\r\n   ```html\r\n   <html>\r\n     <head>\r\n       \x3c!-- Datatables.net CSS file --\x3e\r\n       \x3c!-- See  https://datatables.net/download/index --\x3e\r\n       <link href=\"[...]/datatables.net-dt/css/jquery.dataTables.css\" rel=\"stylesheet\" />\r\n\r\n       \x3c!-- vis CSS file --\x3e\r\n       \x3c!-- See  http://visjs.org/#download_install --\x3e\r\n       <link href=\"[...]/vis/dist/vis.min.css\" rel=\"stylesheet\" type=\"text/css\" />\r\n\r\n       \x3c!-- Gantt CSS file --\x3e\r\n       <link href=\"[...]/dist/css/gantt-jquery.css\" rel=\"stylesheet\" type=\"text/css\" />\r\n     </head>\r\n     <body>\r\n       ...\r\n       \x3c!-- DOM node to contain the Gantt component. --\x3e\r\n       <div id=\"gantt\"></div>\r\n       ...\r\n       \x3c!-- Include jQuery, see https://jquery.com/download/ --\x3e\r\n       <script src=\"[...]/jquery/dist/jquery.min.js\"><\/script>\r\n\r\n       \x3c!-- Datatables.net JS file --\x3e\r\n       \x3c!-- See  https://datatables.net/download/index --\x3e\r\n       <script src=\"[...]/datatables.net/js/jquery.dataTables.js\"><\/script>\r\n\r\n       \x3c!-- vis JS file --\x3e\r\n       \x3c!-- See  http://visjs.org/#download_install --\x3e\r\n       <script src=\"[...]/dist/vis.min.js\"><\/script>\r\n\r\n       \x3c!-- Gantt JS bundle file --\x3e\r\n       <script src=\"[...]/ibm-gantt-chart-jquery.js\"><\/script>\r\n       <script>\r\n         var config = { ... }; // Same format as for the simple Gantt example\r\n         $(document).ready(function() {\r\n             $('#gantt').Gantt(config);\r\n         } );\r\n       <\/script>\r\n     </body>\r\n   </html>\r\n   ```\r\n")},Overview={render:()=>renderMarkdown("## Overview\n\nIBM Gantt Chart lets you visualize data in a Gantt chart on your website.\nA storybook of examples illustrates powerful features that enable a rich experience when using a Gantt chart, from filtering to formatting the display according to the properties of your data.\n\nThe IBM Gantt Chart is packaged in bundles for different uses:\n\n1. As a Vanilla Javascript component\n2. As a React component\n3. As a jQuery component\n\nFor each of these platforms, including a Gantt chart in a website is easy, you just:\n\n- Load one of the Gantt libraries (Vanilla JS, React, jQuery).\n- Create a Gantt Javascript object, giving it a DOM element ID and a configuration object.\n  The configuration object is mainly used to feed the Gantt chart with data, declare a toolbar or configure the display of activities, resources, constraints, breaks, etc.\n- Load some data into the Gantt chart if it is not already specified in the provided configuration object.\n- Insert a DOM element in the HTML using the same ID that you gave to the Gantt object. The DOM element then contains the Gantt component.\n  See [Getting started](./?path=/story/guides-introduction--getting-started) for creating your first Gantt visualization.\n")},Concepts={render:()=>renderMarkdown("## Concepts\n\nA **Gantt chart** is a bar chart that shows time along a horizontal axis and activities placed as bars along the time line. Each activity has a start time and an end time.\nGantt charts are often used to depict planning and scheduling information and also in project management to represent work breakdown structures.\n\nThere are two types of Gantt chart: the **Scheduling chart** and the **Activity Chart**.\n\n**Scheduling charts** show who is doing what and when in your plan. They are used to track simultaneous activities and resources. An **activity** is anything you want to plan, monitor or schedule over time. It has a start and end time (and consequently a duration). A **resource** can be human, machine, equipment or anything you want to use for the activities. A particular assignment of a resource to an activity is called a **reservation**.\n\nFor example, the following diagram shows part of a schedule chart for a building project in August and September. It shows both activities and the resources that are assigned, so that the workload for each resource can be monitored. Different activities (masonry, ceiling, plumbing etc.) are represented as color-coded bars for each resource along a timeline.\nSeveral resources can work simultaneously on the same activity (masonry for example). Some resources work on different activities. Others work only on one type of activity (Steve for example only works on plumbing). The resources section also shows the staff grouped into teams. For example, Jane is responsible for Joe, Jack and Jim but she doesn’t undertake any of the work shown in this scheduling chart.\nAny period that is not filled-in is a period where that resource is not used.\n\n![alt text](images/concepts_schedule_chart.jpg 'Schedule Chart')\n\n**Activity charts** also show when things happen, but they are organized according to the activities rather than the resources. Activities can be broken up into tasks and each task is represented as a horizontal bar along a time scale. You might have some restrictions concerning when different activities start or end in relation to each other. These dependencies are depicted by arrows between activities and are called **constraints**.\n\nThe following diagram shows part of an activity chart for a marketing project in March and April. It displays the order and timing in which different activities must take place. Each activity is broken down into tasks (for example, compiling the customer list and contacting customers are two tasks which make up the activity talking to customers). Arrows between the bars indicate dependencies between activities. For example, the first draft must be completed before the second draft of the marketing requirements can be written. This is indicated by an arrow which indicates that the end of the first draft must occur before the beginning of the second draft. This type of precedence constraint is very common in project management.\n\n![alt text](images/concepts_activity_chart.jpg 'Activity Chart')\n")},__namedExportsOrder=["GettingStarted","Overview","Concepts"];GettingStarted.parameters={...GettingStarted.parameters,docs:{...GettingStarted.parameters?.docs,source:{originalSource:"{\n  render: () => renderMarkdown(gettingStarted)\n}",...GettingStarted.parameters?.docs?.source}}},Overview.parameters={...Overview.parameters,docs:{...Overview.parameters?.docs,source:{originalSource:"{\n  render: () => renderMarkdown(overview)\n}",...Overview.parameters?.docs?.source}}},Concepts.parameters={...Concepts.parameters,docs:{...Concepts.parameters?.docs,source:{originalSource:"{\n  render: () => renderMarkdown(concepts)\n}",...Concepts.parameters?.docs?.source}}}}}]);
//# sourceMappingURL=introduction-stories.d5e4eeae.iframe.bundle.js.map